import { test } from "node:test";
import assert from "node:assert/strict";
import { getEventListeners } from "node:events";
import { setTimeout as sleep } from "node:timers/promises";
import { FlightSearch } from "../src/search/aggregator.ts";
import { Limiter } from "../src/search/limiter.ts";
import type { SupplierOffer } from "../src/search/suppliers.ts";

// A supplier API that answers after delayMs (or never, until aborted). `sent` counts billable requests:
// a request made with an already-aborted signal is never sent, like fetch().
function supplier(name: string, options: { delayMs?: number; never?: boolean; fail?: boolean; offers?: SupplierOffer[] } = {}) {
    const { delayMs = 5, never = false, fail = false, offers = [] } = options;
    const s = {
        name,
        sent: 0,
        aborted: 0,
        search(_query: unknown, signal: AbortSignal): Promise<SupplierOffer[]> {
            if (signal.aborted) return Promise.reject(signal.reason);
            s.sent++;
            return new Promise((resolve, reject) => {
                const onAbort = () => {
                    clearTimeout(timer);
                    s.aborted++;
                    reject(signal.reason);
                };
                const timer = never
                    ? undefined
                    : setTimeout(() => {
                          signal.removeEventListener("abort", onAbort);
                          if (fail) reject(new Error(`${name} returned 502`));
                          else resolve(offers);
                      }, delayMs);
                signal.addEventListener("abort", onAbort, { once: true });
            });
        },
    };
    return s;
}

const query = { from: "LIS", to: "BER", date: "2026-12-18", passengers: 1 };
const offer = (flightNumber: string, price: number, currency = "EUR"): SupplierOffer => ({ flightNumber, departs: "2026-12-18T07:10", price, currency });
const totalSent = (ss: { sent: number }[]) => ss.reduce((n, s) => n + s.sent, 0);

test("offers from every supplier are merged cheapest first, in EUR", async () => {
    const a = supplier("skyhub", { offers: [offer("TP538", 189.99)] });
    const b = supplier("aerolink", { offers: [offer("FR1234", 120, "USD"), offer("XX1", 99, "JPY")] });
    const result = await new FlightSearch([a, b], new Limiter(4), 200).search(query, new AbortController().signal);
    assert.deepEqual(result.offers.map((o) => [o.flightNumber, o.priceCents]), [["FR1234", 11040], ["TP538", 18999]]);
    assert.deepEqual([result.timedOut, result.failed], [[], []]);
});

test("a supplier slower than the budget is cut off and reported as timed out", async () => {
    const fast = supplier("skyhub", { offers: [offer("TP538", 150)] });
    const slow = supplier("legacy-gds", { never: true });
    const result = await new FlightSearch([fast, slow], new Limiter(4), 30).search(query, new AbortController().signal);
    assert.deepEqual(result.offers.map((o) => o.flightNumber), ["TP538"]);
    assert.deepEqual(result.timedOut, ["legacy-gds"]);
    assert.equal(slow.aborted, 1);
});

test("a supplier error is reported without losing the other offers", async () => {
    const ok = supplier("skyhub", { offers: [offer("TP538", 150)] });
    const broken = supplier("aerolink", { fail: true });
    const result = await new FlightSearch([ok, broken], new Limiter(4), 200).search(query, new AbortController().signal);
    assert.deepEqual([result.offers.length, result.failed], [1, ["aerolink"]]);
});

test("a client disconnecting mid-search cancels the supplier requests", async () => {
    const suppliers = [supplier("skyhub", { never: true }), supplier("aerolink", { never: true })];
    const client = new AbortController();
    const pending = new FlightSearch(suppliers, new Limiter(4), 500).search(query, client.signal);
    await sleep(5);
    client.abort();
    await assert.rejects(pending, { name: "AbortError" });
    assert.deepEqual(suppliers.map((s) => s.aborted), [1, 1]);
});

test("a search whose client has already gone never calls the suppliers", async () => {
    const suppliers = [supplier("skyhub"), supplier("aerolink"), supplier("legacy-gds")];
    const client = new AbortController();
    client.abort();
    await assert.rejects(new FlightSearch(suppliers, new Limiter(4), 50).search(query, client.signal), { name: "AbortError" });
    assert.equal(totalSent(suppliers), 0);
});

test("a search cancelled while waiting for a slot sends nothing when its turn comes", async () => {
    const suppliers = [supplier("skyhub", { delayMs: 10 }), supplier("aerolink", { delayMs: 10 }), supplier("legacy-gds", { delayMs: 10 })];
    const search = new FlightSearch(suppliers, new Limiter(1), 100);
    const first = search.search(query, new AbortController().signal);
    const impatient = new AbortController();
    const queued = search.search(query, impatient.signal);
    impatient.abort();
    await first;
    await assert.rejects(queued, { name: "AbortError" });
    console.log("supplier requests sent (one live search = 3):", totalSent(suppliers));
    assert.equal(totalSent(suppliers), 3);
});

test("a finished search leaves no listeners on the client's signal", async () => {
    const client = new AbortController();
    const search = new FlightSearch([supplier("skyhub"), supplier("aerolink")], new Limiter(2), 100);
    for (let i = 0; i < 5; i++) await search.search(query, client.signal);
    assert.equal(getEventListeners(client.signal, "abort").length, 0);
});
